with kept_keys as (select region, city from stores intersect select region, city from stores where opened_date between '2025-05-02' and '2025-10-01'), verified as (select s.* from stores s join kept_keys k on s.region = k.region and s.city = k.city) select city, case when sqft >= 14958 then 'PREMIUM' else 'STANDARD' end as sqft_tier, count(*) filter (where city = 'Tokyo') as tokyo_rows, count(*) filter (where city = 'Tokyo') as tokyo_rows_2, bit_and(sqft) as sqft_bit_and from verified group by 1, 2;
